// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(address actor, uint256 seed) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(uint256(uint160(actor)) % (2**128) != 0 || seed % 2 == 0); // keep domain wide
        // initialize owner balances through the XBornID entry
        vm.prank(address(this));
        c.XBornID();
        // drive a distribution through the public entry getTokens from a fuzzed actor
        vm.startPrank(actor);
        c.getTokens();
        vm.stopPrank();
        // general rule: any admissible distribution leaves the recipient with a positive balance
        assertTrue(c.balanceOf(actor) > 0, "distribution must credit recipient balance");
    }
}
